// SERVER-ONLY. The synthetic demo phantom, generated by lib/shared/phantom.ts (no Node API,
// so the browser build generates the same volume) and cached once per process here as the
// Buffer-carrying volume the API routes serve.
import { generatePhantom } from '../shared/phantom';
import type { AssembledVolume } from './dicom';

export { PHANTOM_ID, PHANTOM_LABEL, PHANTOM_ENTRY, isPhantomId, generatePhantom } from '../shared/phantom';

let cached: AssembledVolume | null = null;

export function getPhantomVolume(): AssembledVolume {
  if (cached) return cached;
  const { meta, voxels } = generatePhantom();
  cached = { meta, data: Buffer.from(voxels.buffer, voxels.byteOffset, voxels.byteLength) };
  return cached;
}
